"use strict";
import { useQuery } from "@tanstack/react-query";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
const V3_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api";
const GET_POOLS_QUERY = `
  query GetPools($token0: String!, $token1: String!) {
    pools(
      where: {
        or: [
          {
            and: [
              { token0: $token0 },
              { token1: $token1 }
            ]
          },
          {
            and: [
              { token0: $token1 },
              { token1: $token0 }
            ]
          }
        ]
      }
      first: 100
      orderBy: totalValueLockedUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
    }
  }
`;
function tickSpacingToFeeAmount(tickSpacing) {
  const TICK_SPACING_TO_FEE = {
    1: 100,
    // tick spacing 1 -> 0.01% fee
    50: 500,
    // tick spacing 50 -> 0.05% fee  
    100: 500,
    // tick spacing 100 -> 0.05% fee
    200: 3e3,
    // tick spacing 200 -> 0.3% fee
    2e3: 1e4
    // tick spacing 2000 -> 1% fee
  };
  return TICK_SPACING_TO_FEE[tickSpacing] || 3e3;
}
function convertSubgraphPoolToRestFormat(pool, chainId) {
  const tickSpacing = parseInt(pool.tickSpacing);
  const feeAmount = tickSpacingToFeeAmount(tickSpacing);
  return {
    poolId: pool.id,
    chainId,
    protocolVersion: ProtocolVersion.V3,
    fee: feeAmount,
    tickSpacing,
    token0: {
      chainId,
      address: pool.token0.id,
      decimals: parseInt(pool.token0.decimals),
      symbol: pool.token0.symbol,
      name: pool.token0.name
    },
    token1: {
      chainId,
      address: pool.token1.id,
      decimals: parseInt(pool.token1.decimals),
      symbol: pool.token1.symbol,
      name: pool.token1.name
    },
    liquidity: pool.liquidity,
    sqrtPrice: pool.sqrtPrice,
    sqrtPriceX96: pool.sqrtPrice,
    // Add both formats for compatibility
    tick: parseInt(pool.tick),
    totalLiquidityUsd: pool.totalValueLockedUSD,
    boostedApr: 0
    // Not available from subgraph
  };
}
async function fetchPoolsFromSubgraph(token0, token1) {
  try {
    const response = await fetch(V3_SUBGRAPH_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query: GET_POOLS_QUERY,
        variables: {
          token0: token0.toLowerCase(),
          token1: token1.toLowerCase()
        }
      })
    });
    const data = await response.json();
    if (data.errors) {
      console.error("Pools query errors:", data.errors);
      return [];
    }
    return data.data?.pools || [];
  } catch (error) {
    console.error("Failed to fetch pools data:", error);
    return [];
  }
}
export function useAbstractPools(input, enabled = true) {
  return useQuery({
    queryKey: ["abstract-pools", input?.token0, input?.token1, input?.chainId, input?.fee],
    queryFn: async () => {
      if (!input?.token0 || !input?.token1 || !input?.chainId) {
        return { pools: [] };
      }
      if (!input.protocolVersions?.includes(ProtocolVersion.V3)) {
        return { pools: [] };
      }
      const subgraphPools = await fetchPoolsFromSubgraph(input.token0, input.token1);
      console.log("Fetched pools from subgraph:", subgraphPools);
      let pools = subgraphPools.map((pool) => convertSubgraphPoolToRestFormat(pool, input.chainId));
      if (input.fee !== void 0) {
        pools = pools.filter((pool) => pool.fee === input.fee);
      }
      console.log("Converted pools for REST API compatibility:", pools);
      return { pools };
    },
    enabled: enabled && !!input?.token0 && !!input?.token1 && !!input?.chainId,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
