"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { CurrencyAmount } from "@uniswap/sdk-core";
import { ErrorCallout } from "components/ErrorCallout";
import { getLPBaseAnalyticsProperties } from "components/Liquidity/analytics";
import { useModalLiquidityInitialState, usePositionDerivedInfo } from "components/Liquidity/hooks";
import { GetHelpHeader } from "components/Modal/GetHelpHeader";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useAccount } from "hooks/useAccount";
import { useModalState } from "hooks/useModalState";
import useSelectChain from "hooks/useSelectChain";
import { canUnwrapCurrency, getCurrencyWithOptionalUnwrap } from "pages/Pool/Positions/create/utils";
import { useMemo, useState } from "react";
import { Trans, useTranslation } from "react-i18next";
import { useAppDispatch } from "state/hooks";
import { liquiditySaga } from "state/sagas/liquidity/liquiditySaga";
import { Button, Flex, Switch, Text } from "ui/src";
import { iconSizes } from "ui/src/theme";
import { CurrencyLogo } from "uniswap/src/components/CurrencyLogo/CurrencyLogo";
import { Modal } from "uniswap/src/components/modals/Modal";
import { nativeOnChain } from "uniswap/src/constants/tokens";
import { uniswapUrls } from "uniswap/src/constants/urls";
import { useAccountMeta } from "uniswap/src/contexts/UniswapContext";
import { useAbstractCollectFees } from "hooks/useAbstractCollectFees";
import { useAbstractV2ClaimFees } from "hooks/useAbstractV2ClaimFees";
import { AccountType } from "uniswap/src/features/accounts/types";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useLocalizationContext } from "uniswap/src/features/language/LocalizationContext";
import { InterfaceEventNameLocal, ModalName } from "uniswap/src/features/telemetry/constants";
import { sendAnalyticsEvent } from "uniswap/src/features/telemetry/send";
import { useCurrencyInfo } from "uniswap/src/features/tokens/useCurrencyInfo";
import {
  LiquidityTransactionType,
  isValidLiquidityTxContext
} from "uniswap/src/features/transactions/liquidity/types";
import { getErrorMessageToDisplay, parseErrorMessageTitle } from "uniswap/src/features/transactions/liquidity/utils";
import { TransactionStepType } from "uniswap/src/features/transactions/steps/types";
import { validateTransactionRequest } from "uniswap/src/features/transactions/swap/utils/trade";
import { currencyId } from "uniswap/src/utils/currencyId";
import { NumberType } from "utilities/src/format/types";
import { logger } from "utilities/src/logger/logger";
import { useTrace } from "utilities/src/telemetry/trace/TraceContext";
import { serializeLiquidityTxContext } from "utils/currencyAmountSerialization";
function UnwrapUnderCard({
  unwrapNativeCurrency,
  setUnwrapNativeCurrency,
  chainId
}) {
  const nativeCurrency = chainId ? nativeOnChain(chainId) : void 0;
  return <Flex
    row
    backgroundColor="$surface2"
    borderBottomLeftRadius="$rounded12"
    borderBottomRightRadius="$rounded12"
    justifyContent="space-between"
    alignItems="center"
    py="$padding8"
    px="$padding16"
  >
      <Text variant="body3" color="$neutral2">
        <Trans i18nKey="pool.collectAs" values={{ nativeWrappedSymbol: nativeCurrency?.symbol }} />
      </Text>
      <Switch
    id="collect-as-weth"
    checked={unwrapNativeCurrency}
    onCheckedChange={() => setUnwrapNativeCurrency((unwrapNativeCurrency2) => !unwrapNativeCurrency2)}
    variant="default"
  />
    </Flex>;
}
export function ClaimFeeModal() {
  const { t } = useTranslation();
  const trace = useTrace();
  const { formatCurrencyAmount } = useLocalizationContext();
  const positionInfo = useModalLiquidityInitialState();
  const account = useAccountMeta();
  const [currentTransactionStep, setCurrentTransactionStep] = useState();
  const [unwrapNativeCurrency, setUnwrapNativeCurrency] = useState(true);
  const { currency0Amount, currency1Amount, chainId } = positionInfo || {};
  const canUnwrap0 = canUnwrapCurrency(currency0Amount?.currency, positionInfo?.version);
  const canUnwrap1 = canUnwrapCurrency(currency1Amount?.currency, positionInfo?.version);
  const canUnwrap = positionInfo && chainId && (canUnwrap0 || canUnwrap1);
  const { closeModal } = useModalState(ModalName.ClaimFee);
  const {
    feeValue0: token0Fees,
    feeValue1: token1Fees,
    fiatFeeValue0: token0FeesUsd,
    fiatFeeValue1: token1FeesUsd
  } = usePositionDerivedInfo(positionInfo);
  const currency0 = getCurrencyWithOptionalUnwrap({
    currency: token0Fees?.currency,
    shouldUnwrap: unwrapNativeCurrency && canUnwrap0
  });
  const currency1 = getCurrencyWithOptionalUnwrap({
    currency: token1Fees?.currency,
    shouldUnwrap: unwrapNativeCurrency && canUnwrap1
  });
  const currencyInfo0 = useCurrencyInfo(currencyId(currency0));
  const currencyInfo1 = useCurrencyInfo(currencyId(currency1));
  const dispatch = useAppDispatch();
  const selectChain = useSelectChain();
  const startChainId = useAccount().chainId;
  const isV2Position = positionInfo?.version === ProtocolVersion.V2;
  const isV3Position = positionInfo?.version === ProtocolVersion.V3;
  const collectFeesEnabled = useMemo(() => {
    if (isV2Position) {
      return Boolean(
        positionInfo?.poolId && account?.address && (token0Fees?.greaterThan(0) || token1Fees?.greaterThan(0))
      );
    } else {
      return Boolean(
        positionInfo?.tokenId && account?.address && (token0Fees?.greaterThan(0) || token1Fees?.greaterThan(0))
      );
    }
  }, [isV2Position, positionInfo?.tokenId, positionInfo?.poolId, account?.address, token0Fees, token1Fees]);
  const v3FeeCollection = useAbstractCollectFees({
    tokenId: positionInfo?.tokenId,
    recipient: account?.address || "",
    enabled: collectFeesEnabled && isV3Position
  });
  const v2FeeCollection = useAbstractV2ClaimFees({
    poolAddress: positionInfo?.poolId || "",
    userAddress: account?.address || "",
    chainId: positionInfo?.chainId || UniverseChainId.Sepolia,
    enabled: collectFeesEnabled && isV2Position
  });
  const { data, isLoading: calldataLoading, error, refetch } = isV2Position ? {
    data: v2FeeCollection.pendingFees0 || v2FeeCollection.pendingFees1 ? {} : null,
    isLoading: false,
    // V2 doesn't need calldata preparation
    error: v2FeeCollection.error ? new Error(v2FeeCollection.error) : null,
    refetch: () => Promise.resolve()
  } : {
    data: v3FeeCollection.data,
    isLoading: v3FeeCollection.isLoading,
    error: v3FeeCollection.error,
    refetch: v3FeeCollection.refetch
  };
  if (error && Object.keys(error).length > 0) {
    const message = parseErrorMessageTitle(error, { defaultTitle: "unknown ClaimLPFeesCalldataQuery" });
    logger.error(message, {
      tags: {
        file: "ClaimFeeModal",
        function: "useEffect"
      }
    });
    sendAnalyticsEvent(InterfaceEventNameLocal.CollectLiquidityFailed, {
      message
    });
  }
  const txInfo = useMemo(() => {
    const validatedTxRequest = validateTransactionRequest(data?.claim);
    if (!positionInfo || !validatedTxRequest) {
      return void 0;
    }
    return {
      type: LiquidityTransactionType.Collect,
      protocolVersion: positionInfo?.version,
      action: {
        type: LiquidityTransactionType.Collect,
        currency0Amount: token0Fees || CurrencyAmount.fromRawAmount(positionInfo.currency0Amount.currency, 0),
        currency1Amount: token1Fees || CurrencyAmount.fromRawAmount(positionInfo.currency1Amount.currency, 0)
      },
      txRequest: validatedTxRequest
    };
  }, [data?.claim, token0Fees, token1Fees, positionInfo]);
  const onPressConfirm = async () => {
    if (!account || account?.type !== AccountType.SignerMnemonic) {
      return;
    }
    if (isV2Position) {
      try {
        setCurrentTransactionStep({ step: TransactionStepType.Confirming, accepted: true });
        const result = await v2FeeCollection.claimFees();
        if (result.success) {
          const positionIdForDisplay = position?.tokenId || (position?.version === ProtocolVersion.V2 ? "V2 LP" : "Unknown");
          const tokenPair = position ? `${position.currency0Amount?.currency.symbol}-${position.currency1Amount?.currency.symbol}` : "Unknown pair";
          const feeAmount = token0Fees && token1Fees ? `${formatCurrencyAmount({ value: token0Fees })} ${token0Fees.currency.symbol} + ${formatCurrencyAmount({ value: token1Fees })} ${token1Fees.currency.symbol}` : "trading fees";
          popupRegistry.addPopup(
            {
              type: PopupType.ClaimFeesSuccess,
              content: {
                type: "success",
                title: "Trading Fees Claimed Successfully",
                description: `Successfully claimed ${feeAmount} from ${tokenPair} position ${positionIdForDisplay}.`,
                hash: result.hash,
                action: "claimFees",
                amount: feeAmount
              }
            },
            `claim-fees-success-${positionIdForDisplay}`
          );
          if (positionInfo && token0Fees?.currency && token1Fees?.currency) {
            sendAnalyticsEvent(InterfaceEventNameLocal.LiquidityFeesClaimed, {
              ...getLPBaseAnalyticsProperties({
                trace,
                poolId: positionInfo.poolId,
                currency0: currencyInfo0?.currency ?? token0Fees.currency,
                currency1: currencyInfo1?.currency ?? token1Fees.currency,
                currency0AmountUsd: token0FeesUsd,
                currency1AmountUsd: token1FeesUsd,
                version: positionInfo?.version
              })
            });
          }
          setCurrentTransactionStep({ step: TransactionStepType.Success, accepted: true });
          setTimeout(() => closeModal(), 2e3);
        } else {
          setCurrentTransactionStep(void 0);
        }
      } catch (error2) {
        console.error("V2 fee claim failed:", error2);
        const positionIdForDisplay = position?.tokenId || (position?.version === ProtocolVersion.V2 ? "V2 LP" : "Unknown");
        popupRegistry.addPopup(
          {
            type: PopupType.ClaimFeesError,
            content: {
              type: "error",
              title: "Failed to Claim Trading Fees",
              description: error2 instanceof Error ? error2.message : "An unexpected error occurred while claiming your trading fees.",
              action: "claimFees"
            }
          },
          `claim-fees-error-${positionIdForDisplay}`
        );
        setCurrentTransactionStep(void 0);
      }
    } else {
      const isValidTx = isValidLiquidityTxContext(txInfo);
      if (!isValidTx) {
        return;
      }
      const serializedTxInfo = serializeLiquidityTxContext(txInfo);
      dispatch(
        liquiditySaga.actions.trigger({
          selectChain,
          startChainId,
          account,
          liquidityTxContext: serializedTxInfo,
          setCurrentStep: setCurrentTransactionStep,
          setSteps: () => void 0,
          onSuccess: () => {
            const positionIdForDisplay = position?.tokenId || (position?.version === ProtocolVersion.V3 ? "V3 NFT" : "Unknown");
            const tokenPair = position ? `${position.currency0Amount?.currency.symbol}-${position.currency1Amount?.currency.symbol}` : "Unknown pair";
            const feeAmount = token0Fees && token1Fees ? `${formatCurrencyAmount({ value: token0Fees })} ${token0Fees.currency.symbol} + ${formatCurrencyAmount({ value: token1Fees })} ${token1Fees.currency.symbol}` : "trading fees";
            popupRegistry.addPopup(
              {
                type: PopupType.ClaimFeesSuccess,
                content: {
                  type: "success",
                  title: "Trading Fees Claimed Successfully",
                  description: `Successfully claimed ${feeAmount} from ${tokenPair} position ${positionIdForDisplay}.`,
                  action: "claimFees",
                  amount: feeAmount
                }
              },
              `claim-fees-success-${positionIdForDisplay}`
            );
            closeModal();
          },
          onFailure: () => {
            const positionIdForDisplay = position?.tokenId || (position?.version === ProtocolVersion.V3 ? "V3 NFT" : "Unknown");
            popupRegistry.addPopup(
              {
                type: PopupType.ClaimFeesError,
                content: {
                  type: "error",
                  title: "Failed to Claim Trading Fees",
                  description: "An unexpected error occurred while claiming your trading fees.",
                  action: "claimFees"
                }
              },
              `claim-fees-error-${positionIdForDisplay}`
            );
            setCurrentTransactionStep(void 0);
          },
          analytics: positionInfo && token0Fees?.currency && token1Fees?.currency ? {
            ...getLPBaseAnalyticsProperties({
              trace,
              poolId: positionInfo.poolId,
              currency0: currencyInfo0?.currency ?? token0Fees.currency,
              currency1: currencyInfo1?.currency ?? token1Fees.currency,
              currency0AmountUsd: token0FeesUsd,
              currency1AmountUsd: token1FeesUsd,
              version: positionInfo?.version
            })
          } : void 0
        })
      );
    }
  };
  return <Modal name={ModalName.ClaimFee} onClose={closeModal} isDismissible>
      <Flex gap="$gap16">
        <GetHelpHeader
    link={uniswapUrls.helpRequestUrl}
    title={t("pool.collectFees")}
    closeModal={closeModal}
    closeDataTestId="ClaimFeeModal-close-icon"
  />
        {token0Fees && token1Fees && <Flex gap="$gap4">
            <Flex
    backgroundColor="$surface2"
    borderTopLeftRadius="$rounded12"
    borderTopRightRadius="$rounded12"
    borderBottomLeftRadius={canUnwrap ? "$rounded0" : "$rounded12"}
    borderBottomRightRadius={canUnwrap ? "$rounded0" : "$rounded12"}
    p="$padding16"
    gap="$gap12"
  >
              <Flex row alignItems="center" justifyContent="space-between">
                <Flex row gap="$gap8" alignItems="center">
                  <CurrencyLogo currencyInfo={currencyInfo0} size={iconSizes.icon24} />
                  <Text variant="body1" color="neutral1">
                    {currency0?.symbol}
                  </Text>
                </Flex>
                <Flex row gap="$gap8" alignItems="center">
                  <Text variant="body1" color="$neutral1">
                    {formatCurrencyAmount({ value: token0Fees })}
                  </Text>
                  {token0FeesUsd && <Text variant="body1" color="$neutral2">
                      ({formatCurrencyAmount({ value: token0FeesUsd, type: NumberType.FiatTokenPrice })})
                    </Text>}
                </Flex>
              </Flex>
              <Flex row alignItems="center" justifyContent="space-between">
                <Flex row gap="$gap8" alignItems="center">
                  <CurrencyLogo currencyInfo={currencyInfo1} size={iconSizes.icon24} />
                  <Text variant="body1" color="neutral1">
                    {currency1?.symbol}
                  </Text>
                </Flex>
                <Flex row gap="$gap8" alignItems="center">
                  <Text variant="body1" color="$neutral1">
                    {formatCurrencyAmount({ value: token1Fees })}
                  </Text>
                  {token1FeesUsd && <Text variant="body1" color="$neutral2">
                      ({formatCurrencyAmount({ value: token1FeesUsd, type: NumberType.FiatTokenPrice })})
                    </Text>}
                </Flex>
              </Flex>
            </Flex>
            {canUnwrap && <UnwrapUnderCard
    unwrapNativeCurrency={unwrapNativeCurrency}
    setUnwrapNativeCurrency={setUnwrapNativeCurrency}
    chainId={chainId}
  />}
          </Flex>}
        <ErrorCallout errorMessage={getErrorMessageToDisplay({ calldataError: error })} onPress={refetch} />
        <Flex row>
          <Button
    key="LoaderButton-animation-ClaimFeeModal-button"
    isDisabled={isV2Position ? !token0Fees?.greaterThan(0) && !token1Fees?.greaterThan(0) || Boolean(currentTransactionStep) : !data?.claim || Boolean(currentTransactionStep)}
    loading={isV2Position ? v2FeeCollection.isLoading || Boolean(currentTransactionStep) : calldataLoading || Boolean(currentTransactionStep)}
    size="large"
    variant="branded"
    onPress={onPressConfirm}
  >
            {currentTransactionStep ? t("common.confirmWallet") : t("common.collect.button")}
          </Button>
        </Flex>
        {
    /* Debug info */
  }
        {process.env.NODE_ENV === "development" && <Text variant="body3" color="$neutral2" mt="$spacing8">
            Debug: hasData={String(!!data)}, hasClaim={String(!!data?.claim)}, 
            loading={String(calldataLoading)}, enabled={String(collectFeesEnabled)}
          </Text>}
      </Flex>
    </Modal>;
}
